/** Indices of the questions that fit a tile. */
export function questionPool(deck: Deck, filter: { area?: string; tag?: string } = {}): number[] {
  const out: number[] = [];
  QUESTIONS[deck].forEach((q, i) => {
    if (filter.area && q.area !== filter.area) return;
    if (filter.tag && q.tag !== filter.tag) return;
    out.push(i);
  });
  return out.length ? out : QUESTIONS[deck].map((_, i) => i);
}

/** Chance (0..1) that each bot answers correctly, by player index (0 = human). */
export const BOT_ACCURACY = [0.7, 0.5, 0.65, 0.8, 0.6];
const LEVEL_SHIFT: Record<string, number> = { Mudah: 0.12, Sedang: 0, Sulit: -0.15 };

/** Base accuracy per offline difficulty; a small per-seat offset keeps bots distinct. */
export const LEVEL_ACCURACY = { mudah: 0.4, sedang: 0.62, sulit: 0.85 } as const;

export function botAccuracy(player: number, tag?: string, level?: keyof typeof LEVEL_ACCURACY): number {
  const base = level ? LEVEL_ACCURACY[level] + ((player % 3) - 1) * 0.04 : (BOT_ACCURACY[player] ?? 0.6);
  return Math.max(0.15, Math.min(0.95, base + (tag ? (LEVEL_SHIFT[tag] ?? 0) : 0)));
}
